import React, { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';

const CompraRespuesta = () => {
    const location = useLocation();
    const [respuesta, setRespuesta] = useState(null);

    useEffect(() => {
        // Parsear los parámetros de la URL
        const queryParams = new URLSearchParams(location.search);
        const paymentStatus = queryParams.get('status'); // ejemplo de parámetro, cambia según la respuesta que esperas
        const paymentId = queryParams.get('payment_id');
        const merchantOrderId = queryParams.get('merchant_order_id');

        setRespuesta({
            status: paymentStatus,
            paymentId: paymentId,
            merchantOrderId: merchantOrderId
        });
    }, [location.search]);

    return (
        <div>
            <h2>Respuesta de la Compra</h2>
            {respuesta ? (
                <div>
                    <p>Status: {respuesta.status}</p>
                    <p>Payment ID: {respuesta.paymentId}</p>
                    <p>Merchant Order ID: {respuesta.merchantOrderId}</p>
                </div>
            ) : (
                <p>Cargando...</p>
            )}
        </div>
    );
};

export default CompraRespuesta;
